Here is the commit message:
kill: fix bug in --all semantic

Introduces by 2ab6683f59cd3371b1c3ac8b5c248d5104ed4d41.

Signed-off-by: Karel Zak <kzak@redhat.com>

Here is the root cause:
The bug was caused by an incorrect logical condition in the process filtering logic, where the check for `ctl.check_all` was set to true instead of false. This led to the unintended filtering of processes by user ID when the `--all` option was specified, contrary to the expected behavior.

Here is the patch:

 int main(int argc, char **argv)
 {
 	struct kill_control ctl = { .numsig = SIGTERM };
 	int nerrs = 0, ct = 0;

 	setlocale(LC_ALL, "");
 	bindtextdomain(PACKAGE, LOCALEDIR);
 	textdomain(PACKAGE);
 	atexit(close_stdout);

 	ctl.do_pid = (!strcmp(program_invocation_short_name, "pid"));	/* Yecch */
 	if (ctl.do_pid)	/* FIXME: remove in March 2016.  */
 		warnx(_("use of 'kill --pid' option as command name is deprecated"));

 	argv = parse_arguments(argc, argv, &ctl);

 	/* The rest of the arguments should be process ids and names. */
 	for ( ; (ctl.arg = *argv) != NULL; argv++) {
 		char *ep = NULL;

 		errno = 0;
 		ctl.pid = strtol(ctl.arg, &ep, 10);
 		if (errno == 0 && ep && *ep == '\0' && ctl.arg < ep) {
 			if (kill_verbose(&ctl) != 0)
 				nerrs++;
 			ct++;
 		} else {
 			struct proc_processes *ps = proc_open_processes();
 			int found = 0;

 			if (!ps)
 				continue;
-			if (ctl.check_all)
+			if (!ctl.check_all)
 				proc_processes_filter_by_uid(ps, getuid());

 			proc_processes_filter_by_name(ps, ctl.arg);
 			while (proc_next_pid(ps, &ctl.pid) == 0) {
 				if (kill_verbose(&ctl) != 0)
 					nerrs++;
 				ct++;
 				found = 1;
 			}
 			proc_close_processes(ps);

 			if (!found) {
 				nerrs++, ct++;
 				warnx(_("cannot find process \"%s\"."), ctl.arg);
 			}
 		}
 	}

 	if (ct && nerrs == 0)
 		return EXIT_SUCCESS;	/* full success */
 	else if (ct == nerrs)
 		return EXIT_FAILURE;	/* all failed */

 	return KILL_EXIT_SOMEOK;	/* partial success */
 }



